// exonous gate for OpenCode, generated by `exonous install` (edits are replaced on the next install).
import { spawn, spawnSync } from "node:child_process";
import { resolve } from "node:path";

const NODE = "__EXONOUS_NODE__";
const PYLE = "__EXONOUS_PYLE__";
const KAIROS = "__EXONOUS_KAIROS__";
const SHELL_TOOLS = ["bash", "shell"];

export const ExonousGate = async ({ directory } = {}) => ({
  "tool.execute.before": async (input, output) => {
    const command = output?.args?.command;
    if (!SHELL_TOOLS.includes(input?.tool) || typeof command !== "string") return;
    const base = directory || process.cwd();
    const cwd = typeof output.args.workdir === "string" ? resolve(base, output.args.workdir) : base;
    const res = spawnSync(NODE, [PYLE, "auto", "--adapter", "opencode"], { input: JSON.stringify({ command, cwd }), encoding: "utf8", timeout: 60000 });
    if (res.status === 2) throw new Error((res.stderr || "").trim() || "exonous: blocked");
    // A gate that cannot run must not wave git or gh through.
    if ((res.error || res.status !== 0) && /\bgit\b|\bgh\b/.test(command)) {
      throw new Error(`exonous: gate unavailable (${res.error ? res.error.message : `exit ${res.status}`}) — blocked; run \`exonous doctor\``);
    }
  },
  event: async ({ event } = {}) => {
    if (event?.type !== "session.created") return;
    try {
      // A session must start even when the update check cannot: spawn errors arrive as an event.
      const child = spawn(NODE, [KAIROS, "--adapter", "opencode"], { detached: true, stdio: "ignore" });
      child.on("error", () => {});
      child.unref();
    } catch {}
  },
});
